changeSet.sql:
INSERT INTO connections (id, connector_code, full_code, user_id, name, enabled) SELECT uuidv7(), 'sessions', 'sessions_' || u.user_id, u.user_id, COALESCE((SELECT name FROM connectors WHERE code = 'sessions'), 'Sessions'), true FROM (SELECT DISTINCT user_id FROM agents WHERE deleted_at IS NULL AND type != 'MCP') u ON CONFLICT (full_code, user_id) WHERE deleted_at IS NULL DO NOTHING;
INSERT INTO agent_connections (agent_id, connection_id) SELECT a.id, c.id FROM agents a JOIN connections c ON c.user_id = a.user_id AND c.connector_code = 'sessions' AND c.deleted_at IS NULL WHERE a.deleted_at IS NULL AND a.type != 'MCP' ON CONFLICT (agent_id, connection_id) WHERE deleted_at IS NULL DO NOTHING;
INSERT INTO agent_skills (user_id, agent_id, skill_id, installed_skill_version) SELECT a.user_id, a.id, s.id, s.version FROM agents a JOIN skills s ON s.name = 'sessions' AND s.user_id = '00000000-0000-0000-0000-000000000000' AND s.deleted_at IS NULL WHERE a.deleted_at IS NULL AND a.type != 'MCP' ON CONFLICT (agent_id, skill_id) DO NOTHING;
INSERT INTO agent_skill_connections (agent_skill_id, connector_key, connection_id) SELECT ag.id, 'sessions', c.id FROM agent_skills ag JOIN skills s ON s.id = ag.skill_id AND s.name = 'sessions' AND s.user_id = '00000000-0000-0000-0000-000000000000' JOIN connections c ON c.user_id = ag.user_id AND c.connector_code = 'sessions' AND c.deleted_at IS NULL ON CONFLICT (agent_skill_id, connector_key) DO NOTHING;
